import subprocess
r = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
pages = r.stdout.split('\x0c')
# Check if 'Limitations' appears on page 8
page8 = pages[7]
if 'Limitations' in page8:
    print('Limitations section IS on page 8')
else:
    print('Limitations section NOT on page 8')
    for i, p in enumerate(pages):
        if 'Limitations' in p:
            print(f'  Found on page {i+1}')
            break
# Check if 'References' appears on page 8
if 'References' in page8:
    print('References header IS on page 8')
# Count body pages (content before References)
for i, p in enumerate(pages):
    if 'References' in p:
        lines = p.split('\n')
        for li, line in enumerate(lines):
            if 'References' in line.strip() and line.strip().endswith('References'):
                print(f'References on page {i+1}, line {li}')
                break
        break
"
